delete msg.headers;
if (context.get('monitoringBusy')) {
  return null;
}
context.set('monitoringBusy', true);
const lastSuccess = context.get('monitoringLastSuccess') || null;
const previousRows = context.get('monitoringRows');
const states = ['waiting', 'active', 'completed', 'failed', 'delayed', 'paused'];
let label = '100 laporan final terbaru';

function status(state, message, last_success_at) {
  return { payload: { state, message, last_success_at } };
}

function projectRows(rows) {
  if (!Array.isArray(rows) || rows.length > 100) {
    throw new Error('Respons data tidak valid');
  }
  const statuses = ['received', 'queued', 'invalid', 'accepted', 'failed'];
  return rows.map(function projectRow(row) {
    if (!row || typeof row !== 'object' || Array.isArray(row)) {
      throw new Error('Baris data tidak valid');
    }
    for (const key of ['message_id', 'timestamp', 'chat_id']) {
      if (typeof row[key] !== 'string') {
        throw new Error('Kolom data tidak valid');
      }
    }
    for (const key of ['sender_id', 'machine', 'notes']) {
      if (row[key] !== null && typeof row[key] !== 'string') {
        throw new Error('Kolom data tidak valid');
      }
    }
    for (const key of ['thickness', 'pressure', 'vacuum']) {
      if (row[key] !== null && (typeof row[key] !== 'number' || !Number.isFinite(row[key]))) {
        throw new Error('Kolom data tidak valid');
      }
    }
    if (!statuses.includes(row.status)) {
      throw new Error('Status data tidak valid');
    }
    return {
      message_id: row.message_id,
      timestamp: row.timestamp,
      chat_id: row.chat_id,
      sender_id: row.sender_id,
      machine: row.machine,
      thickness: row.thickness,
      pressure: row.pressure,
      vacuum: row.vacuum,
      notes: row.notes,
      status: row.status,
    };
  });
}

function summaryText(summary) {
  if (!summary || typeof summary !== 'object' || !summary.queue_counts ||
      !Number.isSafeInteger(summary.reports_accepted) || summary.reports_accepted < 0) {
    throw new Error('Respons ringkasan tidak valid');
  }
  for (const state of states) {
    if (!Number.isSafeInteger(summary.queue_counts[state]) || summary.queue_counts[state] < 0) {
      throw new Error('Jumlah native state tidak valid');
    }
  }
  return 'Native state BullMQ: ' + states.map(function labelCount(state) {
    return state + '=' + summary.queue_counts[state];
  }).join(', ') + '. Laporan final total=' + summary.reports_accepted + '.';
}

try {
  const http = global.get('monitoringHttp');
  const token = global.get('monitoringApiReadToken');
  const view = env.get('MONITORING_VIEW') || 'final';
  const queueState = env.get('MONITORING_QUEUE_STATE') || 'waiting';
  if (!http || typeof http.fetch !== 'function' || typeof token !== 'string' || !token ||
      !['final', 'staging'].includes(view) || !states.includes(queueState)) {
    throw new Error('Konfigurasi adapter tidak valid');
  }
  const base = new http.URL(env.get('MONITORING_API_BASE_URL') || 'http://monitoring-api:3000');
  if (!['http:', 'https:'].includes(base.protocol) || base.username || base.password ||
      base.search || base.hash || base.pathname !== '/') {
    throw new Error('Alamat API harus berupa origin HTTP atau HTTPS');
  }
  if (view === 'staging') {
    label = 'Halaman staging state ' + queueState + ' (offset 0, limit 100)';
  }
  node.send([null, status('loading', label + '. Memuat data dan ringkasan antrean; baris sebelumnya tetap ditampilkan.', lastSuccess)]);

  async function requestJson(path) {
    const controller = new http.AbortController();
    const headers = { Authorization: 'Bearer ' + token, Accept: 'application/json' };
    let timer;
    const deadline = new Promise(function requestDeadline(resolve, reject) {
      timer = setTimeout(function abortRequest() {
        controller.abort();
        reject(new Error('Batas waktu API 4 detik terlampaui'));
      }, 4000);
    });
    try {
      const response = http.fetch(new http.URL(path, base), {
        method: 'GET', headers, signal: controller.signal, redirect: 'error',
      }).then(async function readResponse(result) {
        if (!result.ok) {
          await result.body?.cancel();
          throw new Error('API tidak dapat dibaca');
        }
        return await result.json();
      });
      return await Promise.race([response, deadline]);
    } finally {
      clearTimeout(timer);
      delete headers.Authorization;
      delete headers.Accept;
    }
  }

  const dataPath = '/v1/checklists?view=' + view + '&limit=100' +
    (view === 'staging' ? '&state=' + queueState : '');
  const results = await Promise.allSettled([
    requestJson(dataPath).then(projectRows),
    requestJson('/v1/staging/summary').then(summaryText),
  ]);
  const data = results[0];
  const summary = results[1];
  const queueMessage = summary.status === 'fulfilled'
    ? summary.value
    : 'Ringkasan antrean gagal diperbarui; jumlah native state tidak tersedia.';

  if (data.status === 'rejected') {
    const staleMessage = lastSuccess
      ? 'Data lama dipertahankan dari pembaruan terakhir.'
      : 'Belum ada data berhasil dimuat; tabel tidak diisi dengan data pengganti.';
    return [Array.isArray(previousRows) ? { payload: previousRows } : null,
      status('error', label + '. Gagal memperbarui data. ' + staleMessage + ' ' + queueMessage + ' Coba otomatis pada siklus berikutnya.', lastSuccess)];
  }

  const updatedAt = new Date().toISOString();
  context.set('monitoringRows', data.value);
  context.set('monitoringLastSuccess', updatedAt);
  const dataMessage = data.value.length === 0
    ? 'Tidak ada laporan pada halaman ini.'
    : data.value.length + ' baris ditampilkan; bukan seluruh data server.';
  let state = data.value.length === 0 ? 'empty' : 'ready';
  if (summary.status === 'rejected') {
    state = 'error';
  }
  return [{ payload: data.value }, status(state, label + '. ' + dataMessage + ' ' + queueMessage, updatedAt)];
} catch {
  const staleMessage = lastSuccess ? 'Data lama tetap ditampilkan.' : 'Belum ada data berhasil dimuat.';
  return [Array.isArray(previousRows) ? { payload: previousRows } : null,
    status('error', label + '. Konfigurasi atau akses adapter gagal. Periksa pengaturan server. ' + staleMessage, lastSuccess)];
} finally {
  context.set('monitoringBusy', false);
}
